// A adapter une seule fois : ID du document Grist.
const userId = Number($input.first().json.query.userId);
return [{ json: { docId: 'cRP1WgZQv7KmwmVrUbuEF8', userId } }];

function refId(v) { return Array.isArray(v) ? v[1] : v; }
const cfg = $('Set Config').first().json;
const users = $('Get Users').all().map((i) => i.json).filter((r) => r.id != null);
const pulls = $('Get Pulls').all().map((i) => i.json).filter((r) => r.id != null && refId(r.User) === cfg.userId);
const cards = $('Get Cards').all().map((i) => i.json).filter((r) => r.id != null && r.Active !== false);
const rarities = $('Get Rarities').all().map((i) => i.json).filter((r) => r.id != null);
const trades = $('Get Trades').all().map((i) => i.json).filter((r) => r.id != null);
const extensions = $('Get Extensions').all().map((i) => i.json).filter((r) => r.id != null);

const user = users.find((u) => u.id === cfg.userId);
const cardById = {}; cards.forEach((c) => { cardById[c.id] = c; });
const rarityById = {}; rarities.forEach((r) => { rarityById[r.id] = r; });

const ownedCardIds = new Set(pulls.map((p) => refId(p.Card)));
const uniqueOwned = ownedCardIds.size;

const legendaryUniqueOwned = [...ownedCardIds].filter((cid) => {
  const c = cardById[cid];
  const rarity = c ? rarityById[refId(c.Rarity)] : null;
  return rarity && rarity.Key === 'legendaire';
}).length;

const acceptedTrades = trades.filter((t) => t.Status === 'accepted' && (refId(t.FromUser) === cfg.userId || refId(t.ToUser) === cfg.userId)).length;
const craftedCount = pulls.filter((p) => (p.BatchId || '').toString().startsWith('craft-')).length;

const extensionById = {}; extensions.forEach((e) => { extensionById[e.id] = e; });
const extProgress = {};
cards.forEach((c) => {
  const extId = refId(c.Extension);
  if (extId == null) return;
  if (!extProgress[extId]) extProgress[extId] = { total: 0, owned: 0 };
  extProgress[extId].total++;
  if (ownedCardIds.has(c.id)) extProgress[extId].owned++;
});
// Un succes/badge PAR extension (pas un seul booleen generique) : chaque
// set entierement collectionne devient un succes a part entiere, affichable
// individuellement (panneau de succes, badges de profil).
const setAchievements = Object.entries(extProgress)
  .filter(([, p]) => p.total > 0)
  .map(([extId, p]) => ({ extId: Number(extId), ext: extensionById[Number(extId)], p }))
  .sort((a, b) => (a.ext ? a.ext.SortOrder || 0 : 0) - (b.ext ? b.ext.SortOrder || 0 : 0))
  .map(({ extId, ext, p }) => {
    const name = ext ? ext.Name : 'Extension';
    return {
      key: `set-${extId}`,
      icon: '\u{1F3C6}',
      name: `Set complet : ${name}`,
      description: `Posseder toutes les cartes de l'extension "${name}".`,
      unlocked: p.owned === p.total,
      progress: p.owned,
      goal: p.total
    };
  });
const isFullCollection = cards.length > 0 && uniqueOwned === cards.length;

const totalPulls = (user && user.TotalPulls) || 0;

function tier(value, thresholds, keyPrefix, label, icon) {
  return thresholds.map((t, i) => ({
    key: keyPrefix + (i + 1),
    icon,
    name: label + ' ' + ['I', 'II', 'III', 'IV', 'V'][i],
    description: t.desc,
    unlocked: value >= t.value,
    progress: Math.min(value, t.value),
    goal: t.value
  }));
}

const achievements = [
  { key: 'first-pull', icon: '\u{1F3B4}', name: 'Premier tirage', description: 'Ouvrir ton tout premier booster.', unlocked: totalPulls >= 1, progress: Math.min(totalPulls, 1), goal: 1 },
  ...tier(uniqueOwned, [
    { value: 10, desc: 'Posseder 10 cartes uniques.' },
    { value: 25, desc: 'Posseder 25 cartes uniques.' },
    { value: 50, desc: 'Posseder 50 cartes uniques.' }
  ], 'collector-', 'Collectionneur', '\u{1F4DA}'),
  { key: 'legend-hunter', icon: '\u{1F31F}', name: 'Chasseur de legendes', description: 'Posseder au moins 1 carte legendaire.', unlocked: legendaryUniqueOwned >= 1, progress: Math.min(legendaryUniqueOwned, 1), goal: 1 },
  { key: 'legend-king', icon: '\u{1F451}', name: 'Roi des legendes', description: 'Posseder au moins 5 cartes legendaires differentes.', unlocked: legendaryUniqueOwned >= 5, progress: Math.min(legendaryUniqueOwned, 5), goal: 5 },
  { key: 'trader', icon: '\u{1F91D}', name: 'Negociant', description: 'Conclure 5 echanges.', unlocked: acceptedTrades >= 5, progress: Math.min(acceptedTrades, 5), goal: 5 },
  { key: 'trader-big', icon: '\u{1F4B0}', name: 'Grand negociant', description: 'Conclure 25 echanges.', unlocked: acceptedTrades >= 25, progress: Math.min(acceptedTrades, 25), goal: 25 },
  { key: 'alchemist', icon: '\u2728', name: 'Alchimiste', description: 'Crafter 10 cartes.', unlocked: craftedCount >= 10, progress: Math.min(craftedCount, 10), goal: 10 },
  ...setAchievements,
  { key: 'full-collection', icon: '\u{1F451}', name: 'Collection complete', description: 'Posseder 100% du catalogue.', unlocked: isFullCollection, progress: isFullCollection ? 1 : 0, goal: 1 }
];

return [{ json: { achievements, unlockedCount: achievements.filter((a) => a.unlocked).length, totalCount: achievements.length } }];
